<script setup lang="ts">
import { computed, ref } from 'vue'
import { ArrowUpRightIcon, CheckIcon, DownloadIcon, HeartIcon, MessageCircleIcon, ShieldCheckIcon, SproutIcon } from '@lucide/vue'
import AppInstallDialog from '@/components/common/AppInstallDialog.vue'
import { useWellbeingStore } from '@/stores/wellbeing'
import { useConsultationStore } from '@/stores/consultation'
const wellbeing = useWellbeingStore()
const consultation = useConsultationStore()
const nickname = ref(wellbeing.nickname)
const quiet = ref(wellbeing.quietMotion)
const saved = ref(false)
const showInstall = ref(false)
const exported = ref(false)
const hasUnsaved = computed(() => nickname.value.trim() !== wellbeing.nickname || quiet.value !== wellbeing.quietMotion)
const conversations = computed(() => consultation.sessions.filter(session => session.messages.some(message => message.role === 'user')).length)
function save() { wellbeing.setPreferences(nickname.value, quiet.value); saved.value = true }
function exportRecords() {
  const blob = new Blob([JSON.stringify({ exportedAt: new Date().toISOString(), moodEntries: wellbeing.entries, conversations: consultation.sessions }, null, 2)], { type: 'application/json' })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a'); link.href = url; link.download = `心绘-我的记录-${new Date().toLocaleDateString('sv-SE')}.json`; link.click()
  setTimeout(() => URL.revokeObjectURL(url), 1000); exported.value = true
}
</script>
<template>
  <div class="app-page me-page"><p class="app-eyebrow">A PLACE THAT FEELS LIKE YOU</p><h1>你的专属小空间。</h1><p class="app-subtitle">按喜欢的方式，把自己照顾好一点。</p>
    <section class="profile-card"><span class="profile-avatar">{{ wellbeing.nickname.slice(0,1) || '你' }}</span><div><h2>{{ wellbeing.nickname || '亲爱的你' }}</h2><p>欢迎回来，心绘随时陪你。</p></div><SproutIcon class="profile-sprout" :size="39" :stroke-width="1.2"/></section>
    <div class="personal-stats"><div><HeartIcon :size="18"/><strong>{{ wellbeing.recordedDays }}</strong><span>天的心情被记住</span></div><div><MessageCircleIcon :size="18"/><strong>{{ conversations }}</strong><span>段认真倾听的对话</span></div></div>
    <div class="me-grid"><section class="app-card preference-card"><h2 class="app-section-title">让这里更像你的空间</h2><label for="nickname">希望怎么称呼你？</label><input id="nickname" v-model="nickname" maxlength="20" placeholder="留空也没关系" @input="saved = false"/><div class="motion-preference"><div><strong>安静一点的界面</strong><p>减少浮动与过渡动画，留住平静。</p></div><button class="motion-switch" role="switch" :aria-checked="quiet" aria-label="减少界面动画" @click="quiet = !quiet; saved = false"><span></span></button></div><button class="button primary" :disabled="!hasUnsaved" @click="save"><CheckIcon v-if="saved" :size="16"/>{{ saved && !hasUnsaved ? '偏好已保存' : '保存我的偏好' }}</button><p v-if="wellbeing.storageWarning" class="storage-warning" role="alert">{{ wellbeing.storageWarning }}</p></section>
    <section class="app-card record-card"><span class="privacy-icon"><ShieldCheckIcon :size="24" :stroke-width="1.4"/></span><h2 class="app-section-title">记录的去向，你可以知道</h2><p>心情、昵称和完整对话保存在当前浏览器。清除浏览器数据或换设备后，不会自动恢复。</p><p>聊天时，近期消息与陪伴偏好会发往模型服务，以生成回应。心情日记不会发送。</p><button class="app-text-link" @click="exportRecords"><DownloadIcon :size="16"/>导出我的记录<ArrowUpRightIcon :size="14"/></button><span v-if="exported" class="export-feedback" role="status">记录文件已准备，请查看浏览器下载。</span></section></div>
    <section class="app-card install-card"><span><DownloadIcon :size="22" :stroke-width="1.5"/></span><div><h2>把心绘放在身边</h2><p>了解电脑安装和手机添加到主屏幕的方法。</p></div><button class="button" @click="showInstall = true">查看安装方式<ArrowUpRightIcon :size="15"/></button></section>
    <footer class="me-footer"><p>心绘提供非诊断性的心理支持，不能替代专业咨询或医疗服务。</p><RouterLink to="/">了解心绘官网<ArrowUpRightIcon :size="13"/></RouterLink><span>心绘 · 给心一个柔软的地方</span></footer>
    <AppInstallDialog v-if="showInstall" @close="showInstall = false"/>
  </div>
</template>
